# Puzzle cells: row/column bands are separated by full 8 lines.
H=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
W=H
# Same-color markers connect along any common grid row or column, inclusive.
segments=[(3,[(0,2),(4,2)]),(2,[(1,0),(1,4)]),(2,[(1,0),(3,0)])]
paint={}
for color,pts in segments:
    (r1,c1),(r2,c2)=pts
    if r1==r2:
        cells=[(r1,c) for c in range(min(c1,c2),max(c1,c2)+1)]
    elif c1==c2:
        cells=[(r,c1) for r in range(min(r1,r2),max(r1,r2)+1)]
    else: raise ValueError('not aligned')
    for cell in cells:
        paint[cell]=color if cell not in paint else 6
seps={4,9,14,19,24}
out=[]
for r in range(28):
    row=[]
    for c in range(28):
        if r in seps or c in seps: v=8
        else:
            rb=next(i for i,(a,b) in enumerate(H) if a<=r<b)
            cb=next(i for i,(a,b) in enumerate(W) if a<=c<b)
            v=paint.get((rb,cb),0)
        row.append(v)
    out.append(row)
import json
print(json.dumps(out,separators=(',',':')))
print('cell paint',sorted(paint.items()),'dims',len(out),{len(x) for x in out})

